import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation to test membership of items with a 
    configurable false positive rate. The filter employs a bit array 
    and multiple hash functions to ensure efficient memory usage and 
    fast query response.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self.optimal_size()
        self.num_hashes = self.optimal_num_hashes()
        self.bit_array = [0] * self.size

    def optimal_size(self) -> int:
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def optimal_num_hashes(self) -> int:
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the item using different hash functions."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_value = int(hashlib.md5((item + str(i)).encode('utf-8')).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item might be in the bloom filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

